#include <Arduino.h>

const byte patterns[4] = {0x06, 0x5B, 0x4F, 0x66};

void showStep(byte step) {
  for (byte p = 10; p <= 13; ++p) digitalWrite(p, LOW);
  for (byte s = 0; s < 7; ++s) {
    digitalWrite(2 + s, (patterns[step] & (1 << s)) ? LOW : HIGH);
  }
  digitalWrite(9, HIGH);
  digitalWrite(10 + step, HIGH);
}

void setup() {
  for (byte p = 2; p <= 13; ++p) {
    digitalWrite(p, p <= 9 ? HIGH : LOW);
    pinMode(p, OUTPUT);
  }
  for (byte step = 0; step < 4; ++step) {
    showStep(step);
    delay(1000);
  }
}

void loop() {
  // Retain the final number; subsequent behavior is unspecified.
}
